-- Identity: canonical entity <-> OSDU record (owl:hasKey -> owl:sameAs).
-- Generated by `python -m oag_semantic.platform_knowledge` from the ontology (knowledge/ontology/*.ttl and
-- knowledge/vocabulary.yaml, ADR 0047). Do not edit: change the ontology and regenerate.

-- Needs the OSDU records staged as canonical.osdu_well / canonical.osdu_facility (RECORD_ID + the
-- key columns: UWI; FACILITY_ID, FACILITY_TYPE) before this runs.
CREATE OR ALTER VIEW knowledge.same_as AS
SELECT CONCAT('https://example.org/oag/id/facility/', CAST(c.FACILITY_ID AS VARCHAR(400)), '/', CAST(c.FACILITY_TYPE AS VARCHAR(400))) AS iri, CONCAT('https://example.org/oag/osdu-record/', CAST(r.RECORD_ID AS VARCHAR(400))) AS alias_iri, CAST(r.RECORD_ID AS VARCHAR(400)) AS record_id, 'Facility' AS class_name
FROM canonical.facility c JOIN canonical.osdu_facility r ON c.FACILITY_ID = r.FACILITY_ID AND c.FACILITY_TYPE = r.FACILITY_TYPE
UNION ALL
SELECT CONCAT('https://example.org/oag/id/well/', CAST(c.WELL_ID AS VARCHAR(400))) AS iri, CONCAT('https://example.org/oag/osdu-record/', CAST(r.RECORD_ID AS VARCHAR(400))) AS alias_iri, CAST(r.RECORD_ID AS VARCHAR(400)) AS record_id, 'Well' AS class_name
FROM canonical.well c JOIN canonical.osdu_well r ON c.UWI = r.UWI;
GO
